CREATE TABLE csm_customer_portfolio (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,workshop VARCHAR(60) NOT NULL,planned_capacity INT NOT NULL,active BOOLEAN NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL);
CREATE TABLE csm_user (id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(32) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,full_name VARCHAR(50) NOT NULL,role VARCHAR(20) NOT NULL,customer_portfolio_code VARCHAR(32),enabled BOOLEAN NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL);
CREATE TABLE csm_success_plan (id BIGINT AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(32) NOT NULL UNIQUE,product_code VARCHAR(40) NOT NULL,product_name VARCHAR(120) NOT NULL,customer_portfolio_id BIGINT NOT NULL,planned_qty INT NOT NULL,completed_qty INT NOT NULL,defect_qty INT NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL,batch_no VARCHAR(40),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_order_center FOREIGN KEY(customer_portfolio_id) REFERENCES csm_customer_portfolio(id));
CREATE TABLE csm_touchpoint_record (id BIGINT AUTO_INCREMENT PRIMARY KEY,success_plan_id BIGINT NOT NULL,operation_name VARCHAR(50) NOT NULL,good_qty INT NOT NULL,defect_qty INT NOT NULL,operator_name VARCHAR(50) NOT NULL,reported_at DATETIME(6) NOT NULL,remark VARCHAR(200),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_report_order FOREIGN KEY(success_plan_id) REFERENCES csm_success_plan(id));
CREATE TABLE csm_risk_review (id BIGINT AUTO_INCREMENT PRIMARY KEY,risk_review_no VARCHAR(32) NOT NULL UNIQUE,success_plan_id BIGINT NOT NULL,risk_review_type VARCHAR(30) NOT NULL,risk_review_qty INT NOT NULL,defect_qty INT NOT NULL,result VARCHAR(20) NOT NULL,inspector VARCHAR(50),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_inspection_order FOREIGN KEY(success_plan_id) REFERENCES csm_success_plan(id));
CREATE TABLE csm_health_signal (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,customer_portfolio_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL,oee INT NOT NULL,last_heartbeat DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,CONSTRAINT fk_equipment_center FOREIGN KEY(customer_portfolio_id) REFERENCES csm_customer_portfolio(id));
CREATE INDEX idx_order_status_due ON csm_success_plan(status,due_date); CREATE INDEX idx_report_order_time ON csm_touchpoint_record(success_plan_id,reported_at); CREATE INDEX idx_equipment_status ON csm_health_signal(status);
